test.query:
set -euo pipefail

source_table=rebuilt_projection_merge_source
target_table=rebuilt_projection_merge_target
expected_table=rebuilt_projection_merge_expected

cleanup() {
    $CLICKHOUSE_CLIENT --query "SYSTEM START MERGES $target_table" > /dev/null 2>&1 ||:
}
trap cleanup EXIT

result=$($CLICKHOUSE_CLIENT --multiquery --query "
    SYSTEM STOP MERGES $target_table;
    TRUNCATE TABLE $target_table;
    ALTER TABLE $target_table ATTACH PARTITION ALL FROM $source_table;
    SYSTEM START MERGES $target_table;
    SET min_insert_block_size_rows = 65536, min_insert_block_size_bytes = 0;
    OPTIMIZE TABLE $target_table FINAL;
    SELECT count() = 3000000 AND sum(v) = (SELECT total FROM $expected_table)
    FROM mergeTreeProjection(currentDatabase(), $target_table, p_normal);
    SELECT count() = 65536 AND sumMerge(\`sum(v)\`) = (SELECT total FROM $expected_table)
    FROM mergeTreeProjection(currentDatabase(), $target_table, p_aggregate);
    SELECT count()
    FROM system.projection_parts
    WHERE database = currentDatabase() AND table = '$target_table' AND active;
")

if [[ "$result" != $'1\n1\n2' ]]; then
    printf 'unexpected rebuilt projection result:\n%s\n' "$result" >&2
    exit 1
fi
